429	func transferParamsSig(req TransferRequest) string {
430		// Price 用 omitempty：价款为 0 时签名与引入价款前的旧格式一致，
431		// 旧登记册中落盘的请求仍可按原参数回放；改价则签名不同、按请求号
432		// 冲突拒绝。
433		b, _ := json.Marshal(struct {
434			Kind          string `json:"kind"`
435			ItemID        string `json:"item_id"`
436			ExpectedOwner string `json:"expected_owner"`
437			ExpectedVer   int64  `json:"expected_version"`
438			ToID          string `json:"to_id"`
439			Price         int64  `json:"price,omitempty"`
440			Reason        string `json:"reason"`
441		}{"transfer", req.ItemID, req.ExpectedOwner, req.ExpectedVer, req.ToID, req.Price, req.Reason})
442		return string(b)
443	}
444	
445	// Transfer 由当前持有人发起转让。接收人必须已登记、可用且不同于当前
446	// 持有人；请求必须给出期望持有人与期望版本，藏品不存在或持有人/版本
447	// 不符时返回业务拒绝且不改变任何状态。成交价款（分）由持有人填写，
448	// 非负、未填按 0；成功时按所属系列的版税规则一次落盘各收款账户的
449	// 应付明细与归转让前持有人的余款。同一 (操作者, 请求号) 的相同
450	// 请求重复提交（即使藏品后来已易手）返回首次结果。
451	func (r *Registry) Transfer(req TransferRequest) (TransferResult, error) {
452		if err := req.validatePresent(); err != nil {
453			return TransferResult{}, err
454		}
455		r.mu.Lock()
456		defer r.mu.Unlock()
457		if err := r.checkOpen(); err != nil {
458			return TransferResult{}, err
459		}
460	
461		key := requestKey(req.Operator, req.RequestID)
462		sig := transferParamsSig(req)
463		if prev, ok := r.state.Requests[key]; ok {
464			return r.replayTransfer(prev, sig)
465		}
466	
467		bizErr := r.checkTransfer(req)
468		if bizErr != nil {
469			if !isValidationErr(bizErr) {
470				// 状态类业务拒绝（持有人/版本不符、账户停用、收发同人等）
471				// 占用请求号并落盘，相同参数重提永远返回这一次拒绝。
472				r.state.Requests[key] = request{
473					Operator: req.Operator, RequestID: req.RequestID, Kind: "transfer",
474					Params: sig, Rejected: true, Reason: errCode(bizErr),
475					ItemID: req.ItemID,
476				}
477				_ = r.commit()
478			}
479			// 藏品或账户不存在等校验错误不占用请求号，也不改变持有或历史。
480			return TransferResult{ItemID: req.ItemID, Err: bizErr}, bizErr
481		}
482	
483		h := r.state.Holdings[req.ItemID]
484		seq := r.state.NextSeq + 1
485		r.state.NextSeq = seq
486		from := h.OwnerID
487		fromVer := h.Version
488		h.OwnerID = req.ToID
489		h.Version = fromVer + 1
490		r.state.Holdings[req.ItemID] = h
491		r.state.History = append(r.state.History, historyEntry{
492			Seq: seq, Kind: "transfer", ItemID: req.ItemID, Operator: req.Operator,
493			Reason: req.Reason, RequestID: req.RequestID,
494			FromID: from, ToID: req.ToID, FromVersion: fromVer, ToVersion: fromVer + 1,
495		})
496		// 版税应付与持有变化、历史、请求结果在同一临界区内一次落盘；
497		// 余款归转让前持有人。
498		it := r.state.Items[req.ItemID]
499		royalty := newRoyaltyRec(seq, req.ItemID, it.SeriesID, req.Price,
500			r.state.Series[it.SeriesID].Royalty, from)
501		r.state.Royalties[seq] = royalty
502		r.state.Requests[key] = request{
503			Operator: req.Operator, RequestID: req.RequestID, Kind: "transfer",
504			Params: sig, ItemID: req.ItemID, FromID: from, ToID: req.ToID,
505			Version: fromVer + 1, TxSeq: seq,
506		}
507		if err := r.commit(); err != nil {
508			return TransferResult{}, err
509		}
510		return TransferResult{ItemID: req.ItemID, FromID: from, ToID: req.ToID,
511			Version: fromVer + 1, TxSeq: seq,
512			Price: royalty.Price, Payables: publicPayables(royalty.Payees),
513			Remainder: royalty.Remainder}, nil
514	}
515	
516	func (r *Registry) checkTransfer(req TransferRequest) error {
517		h, ok := r.state.Holdings[req.ItemID]
518		if !ok {
519			if _, itemExists := r.state.Items[req.ItemID]; !itemExists {
520				return fmt.Errorf("%w: 藏品 %s", ErrNotFound, req.ItemID)
521			}
522			return fmt.Errorf("%w: 藏品 %s 没有持有记录", ErrNotFound, req.ItemID)
523		}
524		op, ok := r.state.Accounts[req.Operator]
525		if !ok {
526			return fmt.Errorf("%w: 操作者账户 %s", ErrNotFound, req.Operator)
527		}
528		if !op.Active {
529			return fmt.Errorf("%w: 操作者账户 %s", ErrAccountInactive, req.Operator)
530		}
531		to, ok := r.state.Accounts[req.ToID]
532		if !ok {
533			return fmt.Errorf("%w: 接收账户 %s", ErrNotFound, req.ToID)
534		}
535		if !to.Active {
536			return fmt.Errorf("%w: 接收账户 %s", ErrAccountInactive, req.ToID)
537		}
538		if req.ToID == h.OwnerID {
539			return fmt.Errorf("%w: 接收人 %s 已是当前持有人", ErrSameAccount, req.ToID)
540		}
541		// 期望持有人或期望版本不符，包括发起人并非当前持有人的情况。
542		if h.OwnerID != req.ExpectedOwner || h.Version != req.ExpectedVer ||
543			req.Operator != h.OwnerID {
544			return fmt.Errorf("%w: 藏品 %s 当前为 %s 版本 %d", ErrConflict,
545				req.ItemID, h.OwnerID, h.Version)
546		}
547		return nil
548	}
549	
550	func (r *Registry) replayTransfer(prev request, sig string) (TransferResult, error) {
551		if prev.Kind != "transfer" || prev.Params != sig {
552			return TransferResult{}, fmt.Errorf("%w: 操作者 %s 的请求号 %s 已用于不同请求",
553				ErrRequestConflict, prev.Operator, prev.RequestID)
554		}
555		res := TransferResult{ItemID: prev.ItemID, FromID: prev.FromID, ToID: prev.ToID,
556			Version: prev.Version, TxSeq: prev.TxSeq, Replayed: true}
557		if prev.Rejected {
558			res.Err = codeErr(prev.Reason)
559			return res, res.Err
560		}
561		// 回放首次成功的金额：即使藏品后来再次易手或进程重开，仍返回原
562		// 价款与应付明细，不重复计入。
563		res.Price, res.Payables, res.Remainder = r.royaltyOfTx(prev.TxSeq)
564		return res, nil
565	}
