635			ExpectedVer   int64  `json:"expected_version"`
636			ExpiresAt     string `json:"expires_at"`
637			Price         int64  `json:"price,omitempty"`
638			Reason        string `json:"reason"`
639		}{"auth_create", req.AuthID, req.ItemID, req.TrusteeID, req.ToID,
640			req.ExpectedOwner, req.ExpectedVer,
641			req.ExpiresAt.UTC().Format(time.RFC3339Nano), req.Price, req.Reason})
642		return string(b)
643	}
