645	// CreateAuthorization 由当前持有人为一件已发行藏品创建限时、一次性的
646	// 代转授权：指定唯一授权编号、受托账户、固定接收账户、绝对到期时间，
647	// 以及期望持有人与期望版本。授权绑定创建时的持有版本，不改变持有关系，
648	// 也不限制持有人继续直接转让。受托人不能是授权人；受托人可与接收人
649	// 相同，但接收人也不能是授权人。到期时间必须晚于当前时间。
650	//
651	// 请求号与发行、转让共用同一操作者的请求号范围：相同业务参数重提返回
652	// 首次结果（成功或状态类业务拒绝），参数变化返回 ErrRequestConflict；
653	// 参数错误与引用不存在不占用请求号。
654	func (r *Registry) CreateAuthorization(req CreateAuthorizationRequest) (CreateAuthorizationResult, error) {
655		if err := req.validatePresent(); err != nil {
656			return CreateAuthorizationResult{}, err
657		}
658		r.mu.Lock()
659		defer r.mu.Unlock()
660		if err := r.checkOpen(); err != nil {
661			return CreateAuthorizationResult{}, err
662		}
663	
664		now := r.now()
665		key := requestKey(req.Operator, req.RequestID)
666		sig := createAuthzParamsSig(req)
667		if prev, ok := r.state.Requests[key]; ok {
668			return r.replayCreateAuthz(prev, sig)
669		}
670	
671		if bizErr := r.checkCreateAuthorization(req, now); bizErr != nil {
672			if !isValidationErr(bizErr) {
673				// 状态类业务拒绝（编号占用、停用、同人、版本不符、到期时间
674				// 已过等）占用请求号并落盘；参数错误与引用不存在不占用。
675				r.state.Requests[key] = request{
676					Operator: req.Operator, RequestID: req.RequestID, Kind: "auth_create",
677					Params: sig, Rejected: true, Reason: errCode(bizErr),
678					AuthID: req.AuthID, ItemID: req.ItemID,
679				}
680				_ = r.commit()
681			}
682			return CreateAuthorizationResult{AuthID: req.AuthID, Err: bizErr}, bizErr
683		}
684	
685		h := r.state.Holdings[req.ItemID]
686		a := authzRec{
687			ID: req.AuthID, ItemID: req.ItemID, GranterID: req.Operator,
688			TrusteeID: req.TrusteeID, ToID: req.ToID, ExpiresAt: req.ExpiresAt,
689			GrantVer: h.Version, Price: req.Price, CreatedAt: now,
690		}
691		r.state.Authzs[req.AuthID] = a
692		authSeq := r.state.NextAuthSeq + 1
693		r.state.NextAuthSeq = authSeq
694		r.state.AuthEvents = append(r.state.AuthEvents, authzEvent{
695			Seq: authSeq, AuthID: req.AuthID, ItemID: req.ItemID, Kind: "create",
696			Operator: req.Operator, Reason: req.Reason, RequestID: req.RequestID,
697			FromStatus: "", ToStatus: AuthActive, OccurredAt: now,
698		})
699		r.state.Requests[key] = request{
700			Operator: req.Operator, RequestID: req.RequestID, Kind: "auth_create",
701			Params: sig, AuthID: req.AuthID, ItemID: req.ItemID, Version: h.Version,
702		}
703		if err := r.commit(); err != nil {
704			return CreateAuthorizationResult{}, err
705		}
706		return CreateAuthorizationResult{AuthID: req.AuthID, Status: AuthActive, GrantVer: h.Version}, nil
707	}
708	
709	func (r *Registry) checkCreateAuthorization(req CreateAuthorizationRequest, now time.Time) error {
710		h, ok := r.state.Holdings[req.ItemID]
711		if !ok {
712			if _, itemExists := r.state.Items[req.ItemID]; !itemExists {
713				return fmt.Errorf("%w: 藏品 %s", ErrNotFound, req.ItemID)
714			}
715			return fmt.Errorf("%w: 藏品 %s 没有持有记录", ErrNotFound, req.ItemID)
716		}
717		op, ok := r.state.Accounts[req.Operator]
718		if !ok {
719			return fmt.Errorf("%w: 授权人账户 %s", ErrNotFound, req.Operator)
720		}
721		trustee, ok := r.state.Accounts[req.TrusteeID]
722		if !ok {
723			return fmt.Errorf("%w: 受托人账户 %s", ErrNotFound, req.TrusteeID)
724		}
725		to, ok := r.state.Accounts[req.ToID]
726		if !ok {
727			return fmt.Errorf("%w: 接收账户 %s", ErrNotFound, req.ToID)
728		}
729		if req.TrusteeID == req.Operator {
730			return fmt.Errorf("%w: 受托人不能是授权人 %s", ErrSameAccount, req.Operator)
731		}
732		if req.ToID == req.Operator {
733			return fmt.Errorf("%w: 接收人不能是授权人 %s", ErrSameAccount, req.Operator)
734		}
735		if !op.Active {
736			return fmt.Errorf("%w: 授权人账户 %s", ErrAccountInactive, req.Operator)
737		}
738		if !trustee.Active {
739			return fmt.Errorf("%w: 受托人账户 %s", ErrAccountInactive, req.TrusteeID)
740		}
741		if !to.Active {
742			return fmt.Errorf("%w: 接收账户 %s", ErrAccountInactive, req.ToID)
743		}
744		// 授权编号占用是对象级冲突，优先于当前时间与持有版本检查。
745		if _, exists := r.state.Authzs[req.AuthID]; exists {
746			return fmt.Errorf("%w: 授权编号 %s 已被占用", ErrAlreadyExists, req.AuthID)
747		}
748		// 到期时间不晚于当前时间即为参数错误；从到期时间点起不可使用。
749		if !req.ExpiresAt.After(now) {
750			return fmt.Errorf("%w: 到期时间 %s 必须晚于当前时间",
751				ErrInvalidArgument, req.ExpiresAt.Format(time.RFC3339Nano))
752		}
753		if h.OwnerID != req.ExpectedOwner || h.Version != req.ExpectedVer ||
754			req.Operator != h.OwnerID {
755			return fmt.Errorf("%w: 藏品 %s 当前为 %s 版本 %d",
756				ErrConflict, req.ItemID, h.OwnerID, h.Version)
757		}
758		return nil
759	}
