895	func proxyTransferParamsSig(req ProxyTransferRequest) string {
896		b, _ := json.Marshal(struct {
897			Kind   string `json:"kind"`
898			AuthID string `json:"auth_id"`
899			Reason string `json:"reason"`
900		}{"proxy_transfer", req.AuthID, req.Reason})
901		return string(b)
902	}
903	
904	// ProxyTransfer 由受托人凭授权发起一次性代转。藏品与接收人均以授权
905	// 记载为准，请求本身不能指定。成功后持有人变为授权中的接收人、持有
906	// 版本加一，授权记为已使用并关联该笔转让；代转同样出现在藏品历史中，
907	// 操作者记为实际受托账户并可通过授权编号追溯。
908	//
909	// 非受托人（ErrForbidden）、授权已撤销（ErrAuthorizationRevoked）、
910	// 已到期（ErrAuthorizationExpired）、已使用（ErrAuthorizationUsed）、
911	// 任一相关账户停用（ErrAccountInactive）以及持有版本已变化
912	// （ErrConflict，即使藏品回到授权人手中也不恢复）分别明确拒绝，拒绝
913	// 不改变持有或授权状态。成功代转用原请求号重放时，即使授权已到期、
914	// 账户已停用或藏品再次易手，仍返回首次的转让结果。
915	func (r *Registry) ProxyTransfer(req ProxyTransferRequest) (ProxyTransferResult, error) {
916		missing := []string{}
917		if strings.TrimSpace(req.Operator) == "" {
918			missing = append(missing, "operator")
919		}
920		if strings.TrimSpace(req.Reason) == "" {
921			missing = append(missing, "reason")
922		}
923		if strings.TrimSpace(req.RequestID) == "" {
924			missing = append(missing, "request_id")
925		}
926		if strings.TrimSpace(req.AuthID) == "" {
927			missing = append(missing, "auth_id")
928		}
929		if len(missing) > 0 {
930			return ProxyTransferResult{}, fmt.Errorf("%w: 代转请求缺少必填字段 %s",
931				ErrInvalidArgument, strings.Join(missing, ", "))
932		}
933		r.mu.Lock()
934		defer r.mu.Unlock()
935		if err := r.checkOpen(); err != nil {
936			return ProxyTransferResult{}, err
937		}
938	
939		now := r.now()
940		key := requestKey(req.Operator, req.RequestID)
941		sig := proxyTransferParamsSig(req)
942		if prev, ok := r.state.Requests[key]; ok {
943			return r.replayProxyTransfer(prev, sig)
944		}
945	
946		if bizErr := r.checkProxyTransfer(req, now); bizErr != nil {
947			if !isValidationErr(bizErr) {
948				r.state.Requests[key] = request{
949					Operator: req.Operator, RequestID: req.RequestID, Kind: "proxy_transfer",
950					Params: sig, Rejected: true, Reason: errCode(bizErr), AuthID: req.AuthID,
951				}
952				_ = r.commit()
953			}
954			return ProxyTransferResult{AuthID: req.AuthID, Err: bizErr}, bizErr
955		}
956	
957		a := r.state.Authzs[req.AuthID]
958		h := r.state.Holdings[a.ItemID]
959		seq := r.state.NextSeq + 1
960		r.state.NextSeq = seq
961		from := h.OwnerID
962		fromVer := h.Version
963		h.OwnerID = a.ToID
964		h.Version = fromVer + 1
965		r.state.Holdings[a.ItemID] = h
966		r.state.History = append(r.state.History, historyEntry{
967			Seq: seq, Kind: "transfer", ItemID: a.ItemID, Operator: req.Operator,
968			Reason: req.Reason, RequestID: req.RequestID,
969			FromID: from, ToID: a.ToID, FromVersion: fromVer, ToVersion: fromVer + 1,
970			AuthID: a.ID,
971		})
972		// 代转价款以授权创建时记载为准，执行时不得改价；余款归转让前持有
973		// 人（授权人），不记给受托人。应付明细与持有、历史、授权使用状态
974		// 在同一临界区内一次落盘。
975		it := r.state.Items[a.ItemID]
976		royalty := newRoyaltyRec(seq, a.ItemID, it.SeriesID, a.Price,
977			r.state.Series[it.SeriesID].Royalty, from)
978		r.state.Royalties[seq] = royalty
979		a.Status = "used"
980		a.UsedTxSeq = seq
981		a.UsedAt = now
982		r.state.Authzs[a.ID] = a
983		authSeq := r.state.NextAuthSeq + 1
984		r.state.NextAuthSeq = authSeq
985		r.state.AuthEvents = append(r.state.AuthEvents, authzEvent{
986			Seq: authSeq, AuthID: a.ID, ItemID: a.ItemID, Kind: "use",
987			Operator: req.Operator, Reason: req.Reason, RequestID: req.RequestID,
988			FromStatus: AuthActive, ToStatus: AuthUsed, TxSeq: seq, OccurredAt: now,
989		})
990		r.state.Requests[key] = request{
991			Operator: req.Operator, RequestID: req.RequestID, Kind: "proxy_transfer",
992			Params: sig, AuthID: a.ID, ItemID: a.ItemID, FromID: from, ToID: a.ToID,
993			Version: fromVer + 1, TxSeq: seq,
994		}
995		if err := r.commit(); err != nil {
996			return ProxyTransferResult{}, err
997		}
998		return ProxyTransferResult{AuthID: a.ID, ItemID: a.ItemID, FromID: from,
999			ToID: a.ToID, Version: fromVer + 1, TxSeq: seq,
1000			Price: royalty.Price, Payables: publicPayables(royalty.Payees),
1001			Remainder: royalty.Remainder}, nil
1002	}
1003	
1004	func (r *Registry) checkProxyTransfer(req ProxyTransferRequest, now time.Time) error {
1005		a, ok := r.state.Authzs[req.AuthID]
1006		if !ok {
1007			return fmt.Errorf("%w: 授权 %s", ErrNotFound, req.AuthID)
1008		}
1009		op, ok := r.state.Accounts[req.Operator]
1010		if !ok {
1011			return fmt.Errorf("%w: 受托人账户 %s", ErrNotFound, req.Operator)
1012		}
1013		granter, gOk := r.state.Accounts[a.GranterID]
1014		to, tOk := r.state.Accounts[a.ToID]
1015		if req.Operator != a.TrusteeID {
1016			return fmt.Errorf("%w: 账户 %s 不是授权 %s 的受托人",
1017				ErrForbidden, req.Operator, req.AuthID)
1018		}
1019		if !gOk {
1020			return fmt.Errorf("%w: 授权人账户 %s", ErrNotFound, a.GranterID)
1021		}
1022		if !tOk {
1023			return fmt.Errorf("%w: 接收账户 %s", ErrNotFound, a.ToID)
1024		}
1025		if !op.Active {
1026			return fmt.Errorf("%w: 受托人账户 %s", ErrAccountInactive, req.Operator)
1027		}
1028		if !granter.Active {
1029			return fmt.Errorf("%w: 授权人账户 %s", ErrAccountInactive, a.GranterID)
1030		}
1031		if !to.Active {
1032			return fmt.Errorf("%w: 接收账户 %s", ErrAccountInactive, a.ToID)
1033		}
1034		switch authzCurrentStatus(a, now) {
1035		case AuthRevoked:
1036			return fmt.Errorf("%w: 授权 %s", ErrAuthorizationRevoked, req.AuthID)
1037		case AuthExpired:
1038			return fmt.Errorf("%w: 授权 %s", ErrAuthorizationExpired, req.AuthID)
1039		case AuthUsed:
1040			return fmt.Errorf("%w: 授权 %s", ErrAuthorizationUsed, req.AuthID)
1041		}
1042		// 授权只在创建时绑定的持有版本上有效；版本单调递增，藏品即使回到
1043		// 授权人手中也不会回到旧版本，旧授权据此永久失效。
1044		h, ok := r.state.Holdings[a.ItemID]
1045		if !ok {
1046			return fmt.Errorf("%w: 藏品 %s 没有持有记录", ErrNotFound, a.ItemID)
1047		}
1048		if h.OwnerID != a.GranterID || h.Version != a.GrantVer {
1049			return fmt.Errorf("%w: 藏品 %s 当前为 %s 版本 %d，授权绑定 %s 版本 %d",
1050				ErrConflict, a.ItemID, h.OwnerID, h.Version, a.GranterID, a.GrantVer)
1051		}
1052		return nil
1053	}
1054	
1055	func (r *Registry) replayProxyTransfer(prev request, sig string) (ProxyTransferResult, error) {
1056		if prev.Kind != "proxy_transfer" || prev.Params != sig {
1057			return ProxyTransferResult{}, fmt.Errorf("%w: 操作者 %s 的请求号 %s 已用于不同请求",
1058				ErrRequestConflict, prev.Operator, prev.RequestID)
1059		}
1060		res := ProxyTransferResult{AuthID: prev.AuthID, ItemID: prev.ItemID, FromID: prev.FromID,
1061			ToID: prev.ToID, Version: prev.Version, TxSeq: prev.TxSeq, Replayed: true}
1062		if prev.Rejected {
1063			res.Err = codeErr(prev.Reason)
1064			return res, res.Err
1065		}
1066		// 回放首次成功的金额：授权到期、账户停用或藏品再次易手后仍返回
1067		// 原价款与应付明细，不重复计入。
1068		res.Price, res.Payables, res.Remainder = r.royaltyOfTx(prev.TxSeq)
1069		return res, nil
1070	}
1071	
1072	// ---- 授权查询 ----
1073	
1074	// GetAuthorization 按编号查询授权内容与撤销、使用状态。授权不存在时
1075	// 返回包裹 ErrNotFound 的错误；返回的 Status 按当前时间实时计算，
1076	// 到期但尚未终结的授权返回 AuthExpired。
1077	func (r *Registry) GetAuthorization(authID string) (Authorization, error) {
1078		r.mu.Lock()
1079		defer r.mu.Unlock()
1080		if err := r.checkOpen(); err != nil {
1081			return Authorization{}, err
1082		}
1083		a, ok := r.state.Authzs[authID]
1084		if !ok {
1085			return Authorization{}, fmt.Errorf("%w: 授权 %s", ErrNotFound, authID)
1086		}
1087		return Authorization{
1088			ID: a.ID, ItemID: a.ItemID, GranterID: a.GranterID, TrusteeID: a.TrusteeID,
1089			ToID: a.ToID, ExpiresAt: a.ExpiresAt, GrantVer: a.GrantVer, Price: a.Price,
1090			Status:    authzCurrentStatus(a, r.now()),
1091			UsedTxSeq: a.UsedTxSeq, UsedAt: a.UsedAt, CreatedAt: a.CreatedAt,
1092			RevokedAt: a.RevokedAt,
1093		}, nil
1094	}
1095	
1096	// AuthorizationHistory 按藏品查看授权变更记录（创建、撤销、使用），
1097	// 按发生先后排列；每条记录包含操作者、原因、请求号与前后状态。藏品
1098	// 不存在时返回包裹 ErrNotFound 的错误。
1099	func (r *Registry) AuthorizationHistory(itemID string) ([]AuthorizationEvent, error) {
1100		r.mu.Lock()
1101		defer r.mu.Unlock()
1102		if err := r.checkOpen(); err != nil {
1103			return nil, err
1104		}
1105		if _, ok := r.state.Items[itemID]; !ok {
1106			return nil, fmt.Errorf("%w: 藏品 %s", ErrNotFound, itemID)
1107		}
1108		out := make([]AuthorizationEvent, 0)
1109		for _, e := range r.state.AuthEvents {
1110			if e.ItemID != itemID {
1111				continue
1112			}
1113			out = append(out, AuthorizationEvent{
1114				Seq: e.Seq, AuthID: e.AuthID, ItemID: e.ItemID, Kind: e.Kind,
1115				Operator: e.Operator, Reason: e.Reason, RequestID: e.RequestID,
1116				FromStatus: e.FromStatus, ToStatus: e.ToStatus, TxSeq: e.TxSeq,
1117				OccurredAt: e.OccurredAt,
1118			})
1119		}
1120		return out, nil
1121	}
1122	
1123	// ---- 查询 ----
1124	
1125	// GetItem 查询单件藏品的静态登记信息；不存在时返回包裹 ErrNotFound 的错误。
1126	func (r *Registry) GetItem(id string) (Item, error) {
1127		r.mu.Lock()
1128		defer r.mu.Unlock()
1129		if err := r.checkOpen(); err != nil {
1130			return Item{}, err
1131		}
1132		it, ok := r.state.Items[id]
1133		if !ok {
1134			return Item{}, fmt.Errorf("%w: 藏品 %s", ErrNotFound, id)
1135		}
1136		return Item{ID: it.ID, SeriesID: it.SeriesID, BatchNo: it.BatchNo,
1137			Metadata: it.Metadata, IssuedTxID: it.IssuedTxID}, nil
1138	}
1139	
1140	// GetHolding 查询藏品当前持有状态；藏品不存在时返回包裹 ErrNotFound 的错误。
1141	func (r *Registry) GetHolding(itemID string) (Holding, error) {
1142		r.mu.Lock()
1143		defer r.mu.Unlock()
1144		if err := r.checkOpen(); err != nil {
1145			return Holding{}, err
1146		}
1147		h, ok := r.state.Holdings[itemID]
1148		if !ok {
1149			return Holding{}, fmt.Errorf("%w: 藏品 %s", ErrNotFound, itemID)
1150		}
1151		return Holding{ItemID: h.ItemID, OwnerID: h.OwnerID, Version: h.Version}, nil
1152	}
1153	
1154	// HoldingsOf 查询某账户当前持有的全部藏品。账户不存在时返回包裹
1155	// ErrNotFound 的错误；停用账户仍可正常查询。
1156	func (r *Registry) HoldingsOf(accountID string) ([]Holding, error) {
1157		r.mu.Lock()
1158		defer r.mu.Unlock()
1159		if err := r.checkOpen(); err != nil {
1160			return nil, err
1161		}
1162		if _, ok := r.state.Accounts[accountID]; !ok {
1163			return nil, fmt.Errorf("%w: 账户 %s", ErrNotFound, accountID)
1164		}
1165		out := make([]Holding, 0)
1166		for _, h := range r.state.Holdings {
1167			if h.OwnerID == accountID {
1168				out = append(out, Holding{ItemID: h.ItemID, OwnerID: h.OwnerID, Version: h.Version})
1169			}
1170		}
1171		sort.Slice(out, func(i, j int) bool { return out[i].ItemID < out[j].ItemID })
1172		return out, nil
1173	}
1174	
1175	// History 查询藏品的发行与历次成功转让，按发生先后排列。发行记录的
1176	// 前持有人为空、前版本为 0。重复提交不会产生额外历史。藏品不存在时
1177	// 返回包裹 ErrNotFound 的错误。
1178	func (r *Registry) History(itemID string) ([]HistoryEntry, error) {
1179		r.mu.Lock()
1180		defer r.mu.Unlock()
1181		if err := r.checkOpen(); err != nil {
1182			return nil, err
1183		}
1184		if _, ok := r.state.Items[itemID]; !ok {
1185			return nil, fmt.Errorf("%w: 藏品 %s", ErrNotFound, itemID)
1186		}
1187		out := make([]HistoryEntry, 0)
1188		for _, e := range r.state.History {
1189			if e.ItemID != itemID {
1190				continue
1191			}
1192			out = append(out, HistoryEntry{
1193				Seq: e.Seq, Kind: e.Kind, ItemID: e.ItemID, Operator: e.Operator,
1194				Reason: e.Reason, RequestID: e.RequestID, FromID: e.FromID, ToID: e.ToID,
1195				FromVersion: e.FromVersion, ToVersion: e.ToVersion, AuthID: e.AuthID,
1196			})
1197		}
1198		return out, nil
1199	}
1200	
1201	// ---- 幂等辅助 ----
1202	
1203	func requestKey(operator, requestID string) string {
1204		return operator + "\x00" + requestID
1205	}
1206	
1207	// isValidationErr 判定是否为请求本身不成立的错误：必填缺失，或引用了
1208	// 不存在的账户、系列、藏品。这类请求不占用请求号、不落任何记录，引用
1209	// 对象后来补建后仍可用原请求号完整执行一次；其余拒绝（封存、停用、
1210	// 版本冲突、无权、编号已用、收发同人等状态类业务拒绝）按首次结果记忆
1211	// 并回放。
1212	func isValidationErr(err error) bool {
1213		return errors.Is(err, ErrInvalidArgument) || errors.Is(err, ErrNotFound)
1214	}
1215	
1216	var errCodes = map[error]string{
1217		ErrNotFound:             "not_found",
1218		ErrAlreadyExists:        "already_exists",
1219		ErrAccountInactive:      "account_inactive",
1220		ErrSeriesSealed:         "series_sealed",
1221		ErrConflict:             "conflict",
1222		ErrSameAccount:          "same_account",
1223		ErrForbidden:            "forbidden",
1224		ErrAuthorizationRevoked: "authorization_revoked",
1225		ErrAuthorizationExpired: "authorization_expired",
1226		ErrAuthorizationUsed:    "authorization_used",
1227		ErrRoyaltyFrozen:        "royalty_frozen",
1228	}
1229	
1230	var codeErrs = map[string]error{
1231		"not_found":             ErrNotFound,
1232		"already_exists":        ErrAlreadyExists,
1233		"account_inactive":      ErrAccountInactive,
1234		"series_sealed":         ErrSeriesSealed,
1235		"conflict":              ErrConflict,
1236		"same_account":          ErrSameAccount,
1237		"forbidden":             ErrForbidden,
1238		"authorization_revoked": ErrAuthorizationRevoked,
1239		"authorization_expired": ErrAuthorizationExpired,
1240		"authorization_used":    ErrAuthorizationUsed,
1241		"royalty_frozen":        ErrRoyaltyFrozen,
1242	}
1243	
1244	func errCode(err error) string {
1245		for sentinel, code := range errCodes {
1246			if errors.Is(err, sentinel) {
1247				return code
1248			}
1249		}
1250		return "rejected"
1251	}
1252	
1253	func codeErr(code string) error {
1254		if e, ok := codeErrs[code]; ok {
1255			return e
1256		}
1257		return errors.New("registry: 请求曾被拒绝")
1258	}
