1	package registry
2	
3	import (
4		"errors"
5		"fmt"
6		"os"
7		"path/filepath"
8		"sync"
9		"testing"
10	)
11	
12	func tempDir(t *testing.T) string {
13		t.Helper()
14		dir := t.TempDir()
15		return filepath.Join(dir, "data")
16	}
17	
18	func mustCreate(t *testing.T, dir string) *Registry {
19		t.Helper()
20		r, err := Create(dir)
21		if err != nil {
22			t.Fatalf("Create: %v", err)
23		}
24		t.Cleanup(func() { _ = r.Close() })
25		return r
26	}
27	
28	// setupWorld 建立两个可用账户与一个由 alice 创建的系列。
29	func setupWorld(t *testing.T, r *Registry) {
30		t.Helper()
31		if err := r.RegisterAccount("alice", "创作者"); err != nil {
32			t.Fatal(err)
33		}
34		if err := r.RegisterAccount("bob", "买家"); err != nil {
35			t.Fatal(err)
36		}
37		if err := r.CreateSeries("s1", "alice", "首批系列"); err != nil {
38			t.Fatal(err)
39		}
40	}
41	
42	func issueReq(item, holder string) IssueRequest {
43		return IssueRequest{
44			Operator: "alice", Reason: "首发", RequestID: "req-" + item,
45			ItemID: item, SeriesID: "s1", BatchNo: "b1", Metadata: "元数据", HolderID: holder,
46		}
47	}
48	
49	func xferReq(op, item, to string, ver int64, rid string) TransferRequest {
50		return TransferRequest{
51			Operator: op, Reason: "卖出", RequestID: rid, ItemID: item,
52			ExpectedOwner: op, ExpectedVer: ver, ToID: to,
53		}
54	}
55	
56	// ---- 基础流程 ----
57	
58	func TestBaselineReady(t *testing.T) {
59		if !Ready() {
60			t.Fatal("baseline not ready")
61		}
62	}
63	
64	func TestRegistrationAndIssue(t *testing.T) {
65		r := mustCreate(t, tempDir(t))
66		setupWorld(t, r)
67	
68		res, err := r.Issue(issueReq("item-1", "bob"))
69		if err != nil {
70			t.Fatalf("Issue: %v", err)
71		}
72		if res.Version != 1 || res.OwnerID != "bob" || res.TxSeq != 1 {
73			t.Fatalf("unexpected issue result: %+v", res)
74		}
75		h, err := r.GetHolding("item-1")
76		if err != nil || h.OwnerID != "bob" || h.Version != 1 {
77			t.Fatalf("holding wrong: %+v err=%v", h, err)
78		}
79		hist, err := r.History("item-1")
80		if err != nil || len(hist) != 1 {
81			t.Fatalf("history wrong: %v %v", hist, err)
82		}
83		if e := hist[0]; e.Kind != "issue" || e.FromID != "" || e.FromVersion != 0 ||
84			e.ToID != "bob" || e.ToVersion != 1 || e.Operator != "alice" || e.Reason != "首发" {
85			t.Fatalf("issue history entry wrong: %+v", e)
86		}
87	}
88	
89	func TestTransferFlowAndVersions(t *testing.T) {
90		r := mustCreate(t, tempDir(t))
91		setupWorld(t, r)
92		r.RegisterAccount("carol", "")
93	
94		if _, err := r.Issue(issueReq("item-1", "alice")); err != nil {
95			t.Fatal(err)
96		}
97		res, err := r.Transfer(xferReq("alice", "item-1", "bob", 1, "t1"))
98		if err != nil {
99			t.Fatalf("transfer1: %v", err)
100		}
101		if res.FromID != "alice" || res.ToID != "bob" || res.Version != 2 {
102			t.Fatalf("transfer result wrong: %+v", res)
103		}
104		res, err = r.Transfer(xferReq("bob", "item-1", "carol", 2, "t2"))
105		if err != nil {
106			t.Fatalf("transfer2: %v", err)
107		}
108		if res.Version != 3 || res.ToID != "carol" {
109			t.Fatalf("transfer result wrong: %+v", res)
110		}
111		hist, _ := r.History("item-1")
112		if len(hist) != 3 {
113			t.Fatalf("want 3 history entries, got %d", len(hist))
114		}
115		if e := hist[2]; e.Kind != "transfer" || e.FromID != "bob" || e.ToID != "carol" ||
116			e.FromVersion != 2 || e.ToVersion != 3 {
117			t.Fatalf("last entry wrong: %+v", e)
118		}
119	}
120	
121	func TestHoldingsOfIncludesInactive(t *testing.T) {
122		r := mustCreate(t, tempDir(t))
123		setupWorld(t, r)
124		if _, err := r.Issue(issueReq("item-1", "bob")); err != nil {
125			t.Fatal(err)
126		}
127		if err := r.DeactivateAccount("bob"); err != nil {
128			t.Fatal(err)
129		}
130		hs, err := r.HoldingsOf("bob")
131		if err != nil {
