663		}
664		// 幂等结果也要保留：原转让请求号重放首次成功结果
665		again, err := r2.Transfer(xferReq("alice", "i1", "bob", 1, "t1"))
666		if err != nil || !again.Replayed || again.Version != 2 {
667			t.Fatalf("idempotent result must persist across reopen: %+v %v", again, err)
668		}
669		// 封存状态继续阻止发行
670		if _, err := r2.Issue(issueReq("i2", "bob")); !errors.Is(err, ErrSeriesSealed) {
671			t.Fatalf("seal still blocks after reopen: %v", err)
672		}
673	}
674	
675	// TestPersistenceNoOrphanState 验证"换人必有历史"：快照是单次原子替换，
676	// 磁盘上不会出现持有已变但历史缺失的中间状态。
677	func TestPersistenceNoOrphanState(t *testing.T) {
678		dir := tempDir(t)
679		r := mustCreate(t, dir)
680		setupWorld(t, r)
681		r.Issue(issueReq("i1", "alice"))
682		r.Transfer(xferReq("alice", "i1", "bob", 1, "t1"))
683		// 不调用 Close 直接丢弃（模拟程序被直接终止；flock 由内核释放）。
684		_ = r.store.lock.Close()
685		r.closed = true
686	
687		r2, err := Open(dir)
688		if err != nil {
689			t.Fatal(err)
690		}
691		defer r2.Close()
692		h, _ := r2.GetHolding("i1")
693		hist, _ := r2.History("i1")
694		if h.OwnerID != "bob" || len(hist) != 2 || hist[1].ToID != "bob" {
695			t.Fatalf("state/history must be atomically consistent: holding=%+v hist=%v", h, hist)
696		}
697	}
698	
699	// ---- 数据损坏 / 打开语义 ----
700	
701	func TestCorruptDataRejected(t *testing.T) {
702		dir := tempDir(t)
703		r := mustCreate(t, dir)
704		setupWorld(t, r)
705		r.Close()
706	
707		if err := os.WriteFile(filepath.Join(dir, "registry.json"), []byte("{not json"), fileMode); err != nil {
708			t.Fatal(err)
709		}
710		if _, err := Open(dir); !errors.Is(err, ErrCorrupt) {
711			t.Fatalf("corrupt data must yield ErrCorrupt, got %v", err)
712		}
713		if err := os.WriteFile(filepath.Join(dir, "registry.json"), []byte(""), fileMode); err != nil {
714			t.Fatal(err)
715		}
716		if _, err := Open(dir); !errors.Is(err, ErrCorrupt) {
717			t.Fatalf("empty data must yield ErrCorrupt, got %v", err)
718		}
719	}
720	
721	func TestCreateRefusesExisting(t *testing.T) {
722		dir := tempDir(t)
723		r := mustCreate(t, dir)
724		r.Close()
725		if _, err := Create(dir); !errors.Is(err, ErrAlreadyExists) {
726			t.Fatalf("Create over existing registry must fail, got %v", err)
727		}
728	}
729	
730	func TestOpenEmptyDirIsNotBlankRegistry(t *testing.T) {
731		dir := filepath.Join(t.TempDir(), "fresh")
732		if err := os.MkdirAll(dir, dirMode); err != nil {
733			t.Fatal(err)
734		}
735		if _, err := Open(dir); !errors.Is(err, ErrNotFound) {
736			t.Fatalf("Open on dir with no data must report missing, got %v", err)
737		}
738		// 报错之后目录仍可正常 Create
739		r, err := Create(dir)
740		if err != nil {
741			t.Fatalf("Create after failed Open should work: %v", err)
742		}
743		r.Close()
744	}
745	
746	func TestExclusiveLock(t *testing.T) {
747		dir := tempDir(t)
748		r := mustCreate(t, dir)
749		defer r.Close()
750		if _, err := Open(dir); !errors.Is(err, ErrLocked) {
751			t.Fatalf("second concurrent open must be ErrLocked, got %v", err)
752		}
753	}
754	
755	// ---- 重试语义 ----
756	
757	// 未收到结果的请求用原请求号重试：若首次实际已成功落盘，则回放；
758	// 这里通过"成功后重开再重试"模拟调用方未收到响应的情形。
759	func TestRetryAfterUncertainOutcome(t *testing.T) {
760		dir := tempDir(t)
761		r := mustCreate(t, dir)
762		setupWorld(t, r)
763		r.Issue(issueReq("i1", "alice"))
764		req := xferReq("alice", "i1", "bob", 1, "t1")
765		if _, err := r.Transfer(req); err != nil {
766			t.Fatal(err)
767		}
768		_ = r.store.lock.Close()
769		r.closed = true
770	
771		r2, err := Open(dir)
772		if err != nil {
773			t.Fatal(err)
774		}
775		defer r2.Close()
776		out, err := r2.Transfer(req)
777		if err != nil || !out.Replayed || out.Version != 2 {
778			t.Fatalf("retry must return saved result: %+v %v", out, err)
779		}
780		hist, _ := r2.History("i1")
781		if len(hist) != 2 {
782			t.Fatalf("retry executed twice: %d", len(hist))
783		}
784	}
