func TestBatchIssueMissingFields(t *testing.T) {
	r := mustCreate(t, tempDir(t))
	setupWorld(t, r)

	// 缺操作者
	req := batchReq(batchItem("item-1", "bob"))
	req.Operator = ""
	if _, err := r.BatchIssue(req); !errors.Is(err, ErrInvalidArgument) {
		t.Fatalf("missing operator: %v", err)
	}
