	req = batchReq(batchItem("item-1", "bob"))
	req.Reason = ""
	if _, err := r.BatchIssue(req); !errors.Is(err, ErrInvalidArgument) {
		t.Fatalf("missing reason: %v", err)
	}
	// 缺请求号
	req = batchReq(batchItem("item-1", "bob"))
	req.RequestID = ""
	if _, err := r.BatchIssue(req); !errors.Is(err, ErrInvalidArgument) {
		t.Fatalf("missing request id: %v", err)
	}
	// 缺系列
	req = batchReq(batchItem("item-1", "bob"))
	req.SeriesID = ""
	if _, err := r.BatchIssue(req); !errors.Is(err, ErrInvalidArgument) {
