}

func TestBatchIssueSeriesSealed(t *testing.T) {
	r := mustCreate(t, tempDir(t))
	setupWorld(t, r)
	r.SealSeries("s1", "alice")

	req := batchReq(batchItem("item-1", "bob"))
	if _, err := r.BatchIssue(req); !errors.Is(err, ErrSeriesSealed) {
